sys_script_fix.script:
function getuserstatus(vipstatus) {
    var user = new GlideRecord('sys_user');
    user.addQuery('vip', vipstatus);
    user.query();

    if (vipstatus == true) {
        userstatus = "VIP User"
    } else {
        userstatus = "Non- VIP User"
    }
    return userstatus;
};
getuserstatus(current.caller_id);







